BookSewingBenchHookMaker.ironStock=14; BookSewingBenchHookMaker.bronzeStock=12; BookSewingBenchHookMaker.woodStock=14; BookSewingBenchHookMaker.leatherStock=8; BookSewingBenchHookMaker.silverStock=8; BookSewingBenchHookMaker.goldStock=6; BookSewingBenchHookMaker.jewelStock=4; BookSewingBenchHookMaker.pearlStock=4
BookSewingBenchHookMaker.productStock = {}; BookSewingBenchHookMaker.buildings = {}; BookSewingBenchHookMaker.maker = nil; BookSewingBenchHookMaker.activeMaking = {}; BookSewingBenchHookMaker.totalProducts = 0; BookSewingBenchHookMaker.dayTimer = 0
function BookSewingBenchHookMaker.init() BookSewingBenchHookMaker.ironStock=14; BookSewingBenchHookMaker.bronzeStock=12; BookSewingBenchHookMaker.woodStock=14; BookSewingBenchHookMaker.leatherStock=8; BookSewingBenchHookMaker.silverStock=8; BookSewingBenchHookMaker.goldStock=6; BookSewingBenchHookMaker.jewelStock=4; BookSewingBenchHookMaker.pearlStock=4; BookSewingBenchHookMaker.productStock={}; BookSewingBenchHookMaker.buildings={}; BookSewingBenchHookMaker.maker=nil; BookSewingBenchHookMaker.activeMaking={}; BookSewingBenchHookMaker.totalProducts=0; BookSewingBenchHookMaker.dayTimer=0; print("[BookSewingBenchHookMaker] Royal Book Sewing Bench Hook Maker System initialized (6 products, 4 buildings)") end
function BookSewingBenchHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSewingBenchHookMaker.maker={name=n or ("Kljukar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljukar najet: %s (spretnost: %d)",BookSewingBenchHookMaker.maker.name,s),"success") end; return true end
function BookSewingBenchHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSewingBenchHookMaker.build(id) local ok,e=BookSewingBenchHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSewingBenchHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSewingBenchHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSewingBenchHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSewingBenchHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSewingBenchHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSewingBenchHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSewingBenchHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSewingBenchHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSewingBenchHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSewingBenchHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSewingBenchHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSewingBenchHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSewingBenchHookMaker.buildings==0 then return false,"Potrebna kljukna delavnica" end; if not BookSewingBenchHookMaker.maker then return false,"Potreben kljukar" end; return true end
function BookSewingBenchHookMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSewingBenchHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSewingBenchHookMaker.ironStock=BookSewingBenchHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSewingBenchHookMaker.bronzeStock=BookSewingBenchHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSewingBenchHookMaker.woodStock=BookSewingBenchHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSewingBenchHookMaker.leatherStock=BookSewingBenchHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSewingBenchHookMaker.silverStock=BookSewingBenchHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSewingBenchHookMaker.goldStock=BookSewingBenchHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSewingBenchHookMaker.jewelStock=BookSewingBenchHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSewingBenchHookMaker.pearlStock=BookSewingBenchHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSewingBenchHookMaker.maker then t=math.max(1,t-math.floor(BookSewingBenchHookMaker.maker.skill/13)) end; table.insert(BookSewingBenchHookMaker.activeMaking,{id="booksewingbenchhook_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSewingBenchHookMaker.completeMaking(m) local q=1.0+(BookSewingBenchHookMaker.getQualityBonus()/100); if BookSewingBenchHookMaker.maker then q=q+(BookSewingBenchHookMaker.maker.skill/140) end; q=math.min(2.5,q); BookSewingBenchHookMaker.productStock[m.productType]=(BookSewingBenchHookMaker.productStock[m.productType] or 0)+m.quantity; BookSewingBenchHookMaker.totalProducts=BookSewingBenchHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSewingBenchHookMaker.maker then BookSewingBenchHookMaker.maker.itemsMade=BookSewingBenchHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSewingBenchHookMaker.maker.skill=math.min(100,BookSewingBenchHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljuka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"booksewingbenchhook.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSewingBenchHookMaker.update(dt) if not _G.state then return end; BookSewingBenchHookMaker.dayTimer=BookSewingBenchHookMaker.dayTimer+dt; if BookSewingBenchHookMaker.dayTimer>=30 then BookSewingBenchHookMaker.dayTimer=0; for i=#BookSewingBenchHookMaker.activeMaking,1,-1 do local m=BookSewingBenchHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSewingBenchHookMaker.completeMaking(m); table.remove(BookSewingBenchHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSewingBenchHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSewingBenchHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSewingBenchHookMaker.getStats() return {ironStock=BookSewingBenchHookMaker.ironStock,bronzeStock=BookSewingBenchHookMaker.bronzeStock,woodStock=BookSewingBenchHookMaker.woodStock,leatherStock=BookSewingBenchHookMaker.leatherStock,silverStock=BookSewingBenchHookMaker.silverStock,goldStock=BookSewingBenchHookMaker.goldStock,jewelStock=BookSewingBenchHookMaker.jewelStock,pearlStock=BookSewingBenchHookMaker.pearlStock,productStock=BookSewingBenchHookMaker.productStock,numBuildings=#BookSewingBenchHookMaker.buildings,hasMaker=BookSewingBenchHookMaker.maker~=nil,makerName=BookSewingBenchHookMaker.maker and BookSewingBenchHookMaker.maker.name or "—",makerSkill=BookSewingBenchHookMaker.maker and BookSewingBenchHookMaker.maker.skill or 0,activeMaking=#BookSewingBenchHookMaker.activeMaking,totalProducts=BookSewingBenchHookMaker.totalProducts} end
